import{_ as d,a0 as o,w as n,s as p,ao as c,I as l,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在終端裏按你的方式顯示日期和時間 | LCTT x X-CMD","titleTemplate":false,"description":"在終端裏按你的方式顯示日期和時間 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在終端裏按你的方式顯示日期和時間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在終端裏按你的方式顯示日期和時間 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191127 Displaying dates and times your way","title":"在終端裏按你的方式顯示日期和時間","tag":"201911","desc":""},"relativePath":"201911/20191127 Displaying dates and times your way.md","filePath":"[post].md"}'),h={name:"201911/20191127 Displaying dates and times your way.md"};function r(u,e,g,k,b,m){const i=o("Link");return n(),p("div",null,[e[15]||(e[15]=c(`<h1 id="在終端裏按你的方式顯示日期和時間" tabindex="-1">在終端裏按你的方式顯示日期和時間 <a class="header-anchor" href="#在終端裏按你的方式顯示日期和時間" aria-label="Permalink to “在終端裏按你的方式顯示日期和時間”">​</a></h1><blockquote><p>Linux 的 date 命令提供了很多顯示日期和時間的選項，要比你想的還要多。這是一些有用的選擇。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/29/144555a8mq82mcc9cfttt9.jpg" alt=""></p><p>在 Linux 系統上，<code>date</code> 命令非常簡單。你鍵入 <code>date</code>，日期和時間將以一種有用的方式顯示。它包括星期幾、日期、時間和時區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date</span></span>
<span class="line"><span>Tue 26 Nov 2019 11:45:11 AM EST</span></span></code></pre></div><p>只要你的系統配置正確，你就會看到日期和當前時間以及時區。</p><p>但是，該命令還提供了許多選項來以不同方式顯示日期和時間信息。例如，如果要顯示日期以便進行排序，則可能需要使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%Y-%m-%d&quot;</span></span>
<span class="line"><span>2019-11-26</span></span></code></pre></div><p>在這種情況下，年、月和日按該順序排列。請注意，我們使用大寫字母 <code>Y</code> 來獲得四位數的年份。如果我們使用小寫的 <code>y</code>，則只會看到兩位數字的年份（例如 19）。不要讓這種做法使你錯誤地聯想到如果 <code>％m</code> 給你一個數字月份，<code>％M</code> 可能會給你月份的名稱。不，<code>％M</code> 將給你分鐘數。要以縮寫名稱格式獲得月份，你要使用 <code>％b</code>，而對於完全拼寫的月份，則要使用 <code>％B</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%b %B&quot;</span></span>
<span class="line"><span>Nov November</span></span></code></pre></div><p>或者，你可能希望以這種常用格式顯示日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%D&quot;</span></span>
<span class="line"><span>11/26/19</span></span></code></pre></div><p>如果你需要四位數的年份，則可以執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date &quot;+%x&quot;</span></span>
<span class="line"><span>11/26/2019</span></span></code></pre></div><p>下面是一個可能有用的示例。假設你需要創建一個每日報告並在文件名中包含日期，則可以使用以下命令來創建文件（可能用在腳本中）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch Report-\`date &quot;+%Y-%m-%d&quot;\`</span></span></code></pre></div><p>當你列出你的報告時，它們將按日期順序或反向日期順序（如果你添加 <code>-r</code>）列出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -r Report*</span></span>
<span class="line"><span>Report-2019-11-26</span></span>
<span class="line"><span>Report-2019-11-25</span></span>
<span class="line"><span>Report-2019-11-22</span></span>
<span class="line"><span>Report-2019-11-21</span></span>
<span class="line"><span>Report-2019-11-20</span></span></code></pre></div><p>你還可以在日期字符串中添加其他詳細信息。可用的各種選項多得令人驚訝。你可以使用 <code>date &quot;+%q&quot;</code> 來顯示你所在的一年中的哪個季度，或使用類似以下命令來顯示兩個月前的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date --date=&quot;2 months ago&quot;</span></span>
<span class="line"><span>Thu 26 Sep 2019 09:02:43 AM EDT</span></span></code></pre></div><p>是否想知道下週四的日期？你可以使用類似 <code>date --date=&quot;next thu&quot;</code> 的命令，但是要理解，對於Linux，下個週四意味着今天之後的週四。如果今天是星期三，那就是明天，而不是下週的星期四。但是，你可以像下面的第二個命令一樣指定下週的星期四。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date --date=&quot;next thu&quot;</span></span>
<span class="line"><span>Thu 28 Nov 2019 12:00:00 AM EST</span></span>
<span class="line"><span>$ date --date=&quot;next week thu&quot;</span></span>
<span class="line"><span>Thu 05 Dec 2019 12:00:00 AM EST</span></span></code></pre></div><p><code>date</code> 命令的手冊頁列出了其所有選項。該列表多得令人難以置信，但是你可能會發現一些日期/時間顯示選項非常適合你。以下是一些你可能會發現有趣的東西。</p><p>世界標準時間（UTC）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date -u</span></span>
<span class="line"><span>Tue 26 Nov 2019 01:13:59 PM UTC</span></span></code></pre></div><p>自 1970 年 1 月 1 日以來的秒數（與 Linux 系統上日期的存儲方式有關）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date +%s</span></span>
<span class="line"><span>1574774137</span></span></code></pre></div><p>以下是 <code>date</code> 命令選項的完整列表。正如我所説，它比我們大多數人想像的要廣泛得多。</p><ul><li><code>%%</code> 顯示字母 ％</li><li><code>％a</code> 本地語言環境的縮寫星期名稱（例如，日 / Sun）</li><li><code>％A</code> 本地語言環境的完整星期名稱（例如，星期日 / Sunday）</li><li><code>％b</code> 本地語言環境的縮寫月份名稱（例如 一 / Jan）</li><li><code>％B</code> 本地語言環境的完整月份名稱（例如，一月 / January）</li><li><code>％c</code> 本地語言環境的日期和時間（例如 2005年3月3日 星期四 23:05:25 / Thu Mar 3 23:05:25 2005）</li><li><code>％C</code> 世紀；類似於 <code>％Y</code>，但省略了後兩位數字（例如，20）</li><li><code>%d</code> 月份的天（例如，01）</li><li><code>％D</code> 日期；與 <code>％m/％d/％y</code> 相同</li><li><code>％e</code> 月份的天，填充前綴空格；與 <code>％_d</code> 相同</li><li><code>％F</code> 完整日期；與 <code>％Y-％m-％d</code> 相同</li><li><code>％g</code> ISO 周號的年份的後兩位數字（請參見 <code>％G</code>）</li><li><code>%G</code> ISO 周號的年份（請參閲 <code>％V</code>）；通常僅配合 <code>％V</code> 使用</li><li><code>％h</code> 與 <code>％b</code> 相同</li><li><code>％H</code> 24 小時制的小時（00..23）</li><li><code>％I</code> 12 小時制的小時（01..12）</li><li><code>%j</code> 一年的天（001..366）</li><li><code>％k</code> 24 小時制的小時，填充前綴空格（ 0..23）；與 <code>％_H</code> 相同</li><li><code>％l</code> 12 小時制的小時，填充前綴空格（ 1..12）；與 <code>％_I</code> 相同</li><li><code>％m</code> 月份（01..12）</li><li><code>％M</code> 分鐘（00..59）</li><li><code>％n</code> 換行符</li><li><code>％N</code> 納秒（000000000..999999999）</li><li><code>%p</code> 本地語言環境中等同於 AM 或 PM 的字符串；如果未知，則為空白</li><li><code>％P</code> 像 <code>％p</code>，但使用小寫</li><li><code>％q</code> 季度（1..4）</li><li><code>％r</code> 本地語言環境的 12 小時制時間（例如，晚上 11:11:04 / 11:11:04 PM）</li><li><code>％R</code> 24 小時制的小時和分鐘；與 <code>％H:％M</code> 相同</li><li><code>%s</code> 自 1970-01-01 00:00:00 UTC 以來的秒數</li><li><code>％S</code> 秒（00..60）</li><li><code>％t</code> 製表符</li><li><code>％T</code> 時間；與 <code>％H:％M:％S</code> 相同</li><li><code>％u</code> 星期（1..7）；1 是星期一</li><li><code>％U</code> 年的周號，以星期日為一週的第一天，從 00 開始（00..53）</li><li><code>％V</code> ISO 周號，以星期一為一週的第一天，從 01 開始（01..53）</li><li><code>％w</code> 星期（0..6）；0 是星期日</li><li><code>％W</code> 年的周號，星期一為一週的第一天，從 00 開始（00..53）</li><li><code>％x</code> 本地語言環境的日期表示形式（例如，1999年12月31日 / 12/31/99）</li><li><code>％X</code> 本地語言環境的時間表示形式（例如，23:13:48）</li><li><code>％y</code> 年的最後兩位數字（00..99）</li><li><code>％Y</code> 年份</li><li><code>％z</code> +hhmm 格式的數字時區（例如，-0400）</li><li><code>％:z</code> +hh:mm 格式的數字時區（例如，-04:00）</li><li><code>％::z</code> +hh:mm:ss 格式的數字時區（例如，-04:00:00）</li><li><code>％:::z</code> 數字時區，<code>:</code> 指明精度（例如，-04, +05:30）</li><li><code>％Z</code> 字母時區縮寫（例如，EDT）</li></ul><hr>`,30)),l("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.networkworld.com/article/3481602/displaying-dates-and-times-your-way-with-linux.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3481602/displaying-dates-and-times-your-way-with-linux.html",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const x=d(h,[["render",r]]);export{C as __pageData,x as default};
